// Generated by Viscosity: "tx" stored as a struct of arrays (fields amount, fee, account, day, flags, tax).
class __Vsc_tx {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.amount = new Float64Array(cap); this.fee = new Float64Array(cap); this.account = new Float64Array(cap); this.day = new Float64Array(cap); this.flags = new Float64Array(cap); this.tax = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_tx(Math.max(16, v.length / 6)); for (let i = 0; i < v.length; i += 6) c.push(v[i + 0], v[i + 1], v[i + 2], v[i + 3], v[i + 4], v[i + 5]); return c; }
  push(v0, v1, v2, v3, v4, v5) { const n = this.length; if (n === this.cap) this.grow(); this.amount[n] = v0; this.fee[n] = v1; this.account[n] = v2; this.day[n] = v3; this.flags[n] = v4; this.tax[n] = v5; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.amount); this.amount = t; t = new Float64Array(cap); t.set(this.fee); this.fee = t; t = new Float64Array(cap); t.set(this.account); this.account = t; t = new Float64Array(cap); t.set(this.day); this.day = t; t = new Float64Array(cap); t.set(this.flags); this.flags = t; t = new Float64Array(cap); t.set(this.tax); this.tax = t; }
}
// A ledger of 500k transactions; queries sum one or two fields.
const N = 500000;
const tx = new __Vsc_tx();
for (let i = 0; i < N; i++) {
  tx.push((i % 1000) / 10, (i % 7) / 100, i % 997, i % 365, i % 4, 0.2);
}
function total(t) {
  let s = 0;
  for (let i = 0; i < t.length; i++) s += t.amount[i];
  return s;
}
function feesOn(t, day) {
  let s = 0;
  for (let i = 0; i < t.length; i++) if (t.day[i] === day) s += t.fee[i];
  return s;
}
const t0 = performance.now();
let acc = 0;
for (let r = 0; r < 40; r++) acc += total(tx) + feesOn(tx, r);
const ms = performance.now() - t0;
console.log(JSON.stringify({ check: acc.toFixed(4), ms }));
